from lib import *
S = SS('f131')
R = J('f131'); tm = R['timing']; rc = R['race']
tn, tu = tm['朴素'], tm['统一(不存在的用户也算哈希)']; rn, ra = rc['读出再写回(非原子)'], rc['原子 UPDATE ... WHERE fails < 上限']
steps = [
    step("账号锁定:连续 5 次失败后锁定 2 秒(演示用,生产里是分钟级)。5 次错误密码都是 401;锁定期间用正确的密码也是 401,响应是同一句话「invalid credentials or account temporarily locked」;2 秒后用正确的密码 → 200;成功登录后失败计数清零(0);bob 失败 2 次后成功登录一次,计数也清零。锁定的是一段时间,不是永久,避免被人故意输错来永久封号。", t=tl(S(1)), done=lidx(S(1), '2 秒后', '成功之后', 'bob'), mark=lidx(S(1), '连续 5 次', '锁定期间'), kv=KV([['达到上限', '锁定一段时间'], ['锁定期间', '正确密码也拒绝'], ['成功登录', '计数清零']], ['达到上限'])),
    step("响应不要泄漏「用户名存不存在」:朴素实现对不存在的用户返回 404「user not found」,对存在但密码错的用户返回 401「wrong password」,调用方凭状态码与消息就能枚举账号;统一实现两种情况都是 401 与同一句话,锁定期间也是同一句话。", t=tl(S(2)), mark=lidx(S(2), '朴素', '404', 'wrong password'), done=lidx(S(2), '统一'), kv=KV([['朴素', '404 与 401,消息不同,可枚举账号'], ['统一', '都是 401 同一句话']], ['统一'])),
    step(f"时间差也会泄漏:朴素实现对不存在的用户不做哈希,只要 {tn[0]:.1f} ms,存在的用户做一次密码哈希要 {tn[1]:.1f} ms,差 {tn[1] - tn[0]:.1f} ms,计时就能分辨账号是否存在;统一实现对不存在的用户也对一个固定的假哈希算一次,两者是 {tu[0]:.1f} ms 与 {tu[1]:.1f} ms,差 {tu[1] - tu[0]:.1f} ms。(这里是 test client 里 10 次中位数,没有在网络抖动下验证。)", b=bars([['朴素 不存在', max(tn[0], 0.5), f'{tn[0]:.1f} ms'], ['朴素 存在', tn[1], f'{tn[1]:.1f} ms'], ['统一 不存在', tu[0], f'{tu[0]:.1f} ms'], ['统一 存在', tu[1], f'{tu[1]:.1f} ms']], tn[1], mark=[0], done=[2, 3]), t=tl(S(3)), mark=lidx(S(3), '朴素'), done=lidx(S(3), '统一'), kv=KV([['朴素', f'差 {tn[1] - tn[0]:.0f} ms'], ['统一(假哈希)', f'差 {tu[1] - tu[0]:.1f} ms']], ['统一(假哈希)'])),
    step(f"并发下计数要原子:20 个线程同时发 20 次错误密码,上限 5。读出失败次数、加 1、再写回(非原子)的实现里,{rn[0]} 次尝试都真正去校验了密码,没有一个被拒绝——并发请求读到的都是旧计数,上限形同虚设;用一条原子的 UPDATE acct SET fails = fails + 1 WHERE fails < 上限 RETURNING 先占名额,只有 {ra[0]} 次尝试去校验密码,{ra[1]} 次直接被拒绝(423)。", b=bars([['非原子 去校验的次数', rn[0], str(rn[0])], ['原子 去校验的次数', ra[0], str(ra[0])]], 20, mark=[0], done=[1]), t=tl(S(4)), mark=lidx(S(4), '读出再写回'), done=lidx(S(4), '原子'), kv=KV([['读出再写回', f'{rn[0]} / 20 都放行'], ['原子 UPDATE', f'只放行 {ra[0]} 次']], ['原子 UPDATE'])),
]
A = mkartf('f131', 131, 'Flask,登录锁定,账号保护,并发,真实验证,动画演示',
    f'实测登录失败锁定的设计细节:失败 5 次后锁定一段时间、锁定期间正确密码也被拒、成功登录清零;用统一响应避免枚举账号;不存在的用户也做一次假哈希把响应时间差从 {tn[1] - tn[0]:.0f} ms 压到 {tu[1] - tu[0]:.1f} ms;并发下非原子计数 20 次全部放行而原子 UPDATE 只放行 5 次。',
    '登录失败多少次该锁?怎么锁才不会被人拿来封号?响应和时间会不会泄漏账号是否存在?并发请求能不能绕过计数?这篇在真实的 PostgreSQL 上把这些细节逐个验证(只验证防护这一端)。',
    [(f'{tn[1] - tn[0]:.0f} → {tu[1] - tu[0]:.1f} ms', '存在与不存在的用户的响应时间差:朴素实现与统一实现'), (f'{rn[0]} → {ra[0]}', '20 个并发错误尝试里真正去校验密码的次数:非原子计数与原子计数(上限 5)'), ('同一句话', '统一响应里对不存在的用户、密码错误、账号锁定都返回的消息')],
    [('锁定与恢复', '<p>上一篇:<a href="flask-password-hash-upgrade.html">密码哈希与密码升级</a>;下一篇:<a href="flask-debugger-risk.html">开发模式 Debugger 风险</a>。</p><p>第 129 篇讲过用 Flask-Limiter 限流,这一篇讲应用层的账号锁定。</p>'), ('统一的响应', None), ('响应时间', None), ('并发与原子计数', '<p>并发用 20 个线程同时发请求(各自的 test client 与数据库连接),数据库是自己起的 PostgreSQL。</p>')],
    steps, [ENV_F + '。Flask-SQLAlchemy 3.1.1、自己起的 PostgreSQL(非默认端口)、Werkzeug pbkdf2:sha256:600000 哈希', '没有验证:渐进式延迟(退避)与验证码的效果、锁定通知邮件、管理员解锁流程、分布式多实例下计数的存放位置(redis)、时间差在真实网络抖动下的可检测性'], '登录失败锁定')
